insert into public.words select * from jsonb_populate_record(null::public.words, $json${"id": "248", "word": "로판", "likes": 0, "saves": 0, "usage": "웹소설·웹툰 취향을 말할 때 장르 이름으로 쓴다. 알파벳 없이 '로맨스판타지'로 검색해도 이 항목 하나가 나온다.", "origin": "'로맨스 판타지'의 앞 글자를 딴 줄임말. 2010년대 후반 조아라·카카오페이지·리디 같은 연재 플랫폼에서 로맨스와 판타지를 섞은 작품이 한 덩어리로 묶이면서 장르 이름으로 굳었다.", "aliases": ["로맨스판타지"], "category": "drama", "meanings": [{"type": "명사", "examples": [{"de": "Ich lese in letzter Zeit nur noch Romantasy.", "es": "Últimamente solo leo romantasy.", "ja": "最近ロマンスファンタジーばっかり読んでる。", "vi": "Dạo này mình chỉ đọc mỗi romantasy.", "eng": "Lately I only read romantasy.", "kor": "요즘 로판만 읽어."}, {"de": "In dieser Romantasy wird die Heldin wiedergeboren und ändert alles.", "es": "En este romantasy la protagonista renace y lo cambia todo.", "ja": "このロマンスファンタジー、ヒロインが転生して全部変えるんだよ。", "vi": "Bộ romantasy này nữ chính tái sinh rồi đổi hết mọi thứ.", "eng": "In this romantasy the heroine is reborn and changes everything.", "kor": "이 로판 여주가 회귀해서 다 뒤집어."}], "definition": "'로맨스 판타지'의 줄임말로, 서양 중세풍 왕국이나 귀족 사회를 배경에 두고 여성 주인공의 이야기를 중심에 놓는 웹소설·웹툰 장르. 회귀·빙의·환생(회빙환)으로 인생을 다시 사는 설정이 대표 클리셰다.", "definition_i18n": {"de": "Kurz für 'Romance Fantasy' — ein Webroman- und Webtoon-Genre, das in mittelalterlich-europäischen Königreichen oder Adelsgesellschaften spielt und die Geschichte einer weiblichen Hauptfigur ins Zentrum stellt. Das typische Klischee ist ein zweites Leben durch Zeitsprung, Seelenwanderung oder Wiedergeburt.", "en": "Short for 'romance fantasy' — a webnovel and webtoon genre set in medieval-European kingdoms or noble society, centred on a female lead. Its signature cliche is living life over again through regression, body-swapping or rebirth.", "es": "Abreviatura de 'romance fantasy': un género de webnovelas y webtoons ambientado en reinos medievales europeos o en la nobleza, centrado en una protagonista femenina. Su cliché insignia es volver a vivir la vida mediante regresión, posesión o reencarnación.", "ja": "「ロマンスファンタジー」の略で、中世ヨーロッパ風の王国や貴族社会を舞台にヒロインの物語を中心に据えるウェブ小説・ウェブトゥーンのジャンル。回帰・憑依・転生で人生をやり直す設定が代表的なお約束。", "vi": "Viết tắt của 'romance fantasy' — thể loại truyện mạng và webtoon lấy bối cảnh vương quốc, giới quý tộc kiểu trung cổ châu Âu, xoay quanh nữ chính. Mô típ đặc trưng là sống lại cuộc đời nhờ hồi quy, nhập hồn hoặc tái sinh."}}], "created_at": "2026-09-04T09:30:00+00:00", "short_desc": "'로맨스 판타지' 줄임말 — 여주인공 중심의 웹소설·웹툰 장르", "usage_i18n": {"de": "Wird als Genrename verwendet, wenn man über seinen Webroman- oder Webtoon-Geschmack spricht. Auch die ausgeschriebene Form 로맨스판타지 führt zu genau diesem einen Eintrag.", "en": "Used as a genre label when talking about your webnovel or webtoon taste. The spelled-out 로맨스판타지 leads to this same single entry.", "es": "Se usa como nombre de género al hablar de tus gustos en webnovelas o webtoons. La forma completa 로맨스판타지 lleva a esta misma entrada.", "ja": "ウェブ小説・ウェブトゥーンの好みを話す時にジャンル名として使う。省略しない「로맨스판타지」で検索しても同じこの一件が出る。", "vi": "Dùng như tên thể loại khi nói về gu truyện mạng hay webtoon. Gõ đầy đủ 로맨스판타지 cũng ra đúng mục này."}, "origin_i18n": {"de": "Aus den ersten Silben von 'Romance Fantasy' gebildet. In der zweiten Hälfte der 2010er bündelten Plattformen wie Joara, KakaoPage und Ridi Werke, die Romanze und Fantasy mischen, zu einem Block — daraus wurde ein fester Genrename.", "en": "Formed from the first syllables of 'romance fantasy.' In the late 2010s, serialisation platforms such as Joara, KakaoPage and Ridi grouped works blending romance and fantasy into one block, and the label stuck as a genre name.", "es": "Formado con las primeras sílabas de 'romance fantasy.' A finales de los 2010, plataformas de serialización como Joara, KakaoPage y Ridi agruparon las obras que mezclan romance y fantasía en un solo bloque, y la etiqueta cuajó como nombre de género.", "ja": "「ロマンス ファンタジー」の頭を取った略語。2010年代後半にジョアラ・カカオページ・リディといった連載プラットフォームでロマンスとファンタジーを混ぜた作品が一つの塊にまとめられ、ジャンル名として定着した。", "vi": "Ghép âm đầu của 'romance fantasy.' Cuối thập niên 2010, các nền tảng đăng truyện như Joara, KakaoPage, Ridi gom các tác phẩm pha trộn lãng mạn và kỳ ảo thành một nhóm, và cái tên đọng lại thành tên thể loại."}, "romanization": "Ro-pan", "translations": [{"lang": "🇺🇸 EN", "text": "Romantasy (romance fantasy)"}, {"lang": "🇯🇵 JA", "text": "ロマンスファンタジー"}, {"lang": "🇨🇳 ZH", "text": "言情奇幻"}, {"lang": "🇻🇳 VI", "text": "Romance fantasy"}, {"lang": "🇪🇸 ES", "text": "Romantasy"}, {"lang": "🇩🇪 DE", "text": "Romantasy"}], "pronunciation": "[로판]", "related_words": ["떡밥", "정주행"], "short_desc_i18n": {"de": "Kurz für 'Romance Fantasy' — ein Webroman-Genre mit weiblicher Hauptfigur", "en": "Short for 'romance fantasy' — a webnovel genre with a female lead", "es": "Abreviatura de 'romance fantasy' — un género de webnovela con protagonista femenina", "ja": "「ロマンスファンタジー」の略、ヒロイン中心のウェブ小説ジャンル", "vi": "Viết tắt của 'romance fantasy' — thể loại truyện mạng lấy nữ chính làm trung tâm"}}$json$::jsonb);

